const http = require('http');
const url = require('url');
const dns = require('dns');
const { promisify } = require('util');

const dnsResolve = promisify(dns.resolve4);

// Configuration loaded from environment
const CONFIG = {
  port: parseInt(process.env.APP_PORT || '3000'),
  trustedOrigins: (process.env.TRUSTED_ORIGINS || 'localhost,127.0.0.1').split(','),
  internalApiHost: process.env.INTERNAL_API || 'http://169.254.169.254',
  enableHostValidation: process.env.ENABLE_HOST_VALIDATION !== 'false',
  dnsResolutionTimeout: parseInt(process.env.DNS_TIMEOUT || '2000'),
  allowedNetworkPrefix: process.env.ALLOWED_NETWORK || '10.0.0',
  maxRequestsPerMinute: parseInt(process.env.RATE_LIMIT || '60'),
};

const requestCounts = new Map();

function isPrivateIP(ip) {
  const parts = ip.split('.').map(Number);
  if (parts[0] === 10) return true;
  if (parts[0] === 172 && parts[1] >= 16 && parts[1] <= 31) return true;
  if (parts[0] === 192 && parts[1] === 168) return true;
  if (parts[0] === 169 && parts[1] === 254) return true;
  if (ip === '127.0.0.1') return true;
  return false;
}

async function validateHostHeader(hostHeader) {
  if (!CONFIG.enableHostValidation) return true;

  const hostname = hostHeader.split(':')[0].toLowerCase().trim();

  // Check against trusted origins
  if (CONFIG.trustedOrigins.includes(hostname)) {
    return true;
  }

  // Resolve DNS to check if it points to a trusted IP
  try {
    const addresses = await dnsResolve(hostname);
    const firstResolution = addresses[0];

    // Verify the resolved IP is in our allowed network
    if (firstResolution.startsWith(CONFIG.allowedNetworkPrefix)) {
      return true;
    }
  } catch (e) {
    // DNS resolution failed - could be a local hostname
    return CONFIG.trustedOrigins.some(origin => hostname.endsWith('.' + origin));
  }

  return false;
}

function rateLimit(clientIP) {
  const now = Date.now();
  const windowStart = now - 60000;

  if (!requestCounts.has(clientIP)) {
    requestCounts.set(clientIP, []);
  }

  const timestamps = requestCounts.get(clientIP).filter(t => t > windowStart);
  timestamps.push(now);
  requestCounts.set(clientIP, timestamps);

  return timestamps.length <= CONFIG.maxRequestsPerMinute;
}

async function proxyInternalRequest(targetPath) {
  return new Promise((resolve, reject) => {
    const targetUrl = `${CONFIG.internalApiHost}${targetPath}`;
    const parsed = url.parse(targetUrl);

    const req = http.get({
      hostname: parsed.hostname,
      port: parsed.port || 80,
      path: parsed.path,
      timeout: CONFIG.dnsResolutionTimeout,
    }, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => resolve({ status: res.statusCode, body: data }));
    });

    req.on('error', reject);
    req.on('timeout', () => { req.destroy(); reject(new Error('timeout')); });
  });
}

async function handleApiRequest(req, res, pathname) {
  const targetPath = pathname.replace('/api/proxy', '') || '/';

  try {
    const result = await proxyInternalRequest(targetPath);
    res.writeHead(result.status, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ data: result.body }));
  } catch (err) {
    res.writeHead(502, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'upstream_error' }));
  }
}

const server = http.createServer(async (req, res) => {
  const clientIP = req.socket.remoteAddress;

  if (!rateLimit(clientIP)) {
    res.writeHead(429);
    res.end('Rate limited');
    return;
  }

  const hostHeader = req.headers.host || '';
  const hostValid = await validateHostHeader(hostHeader);

  if (!hostValid) {
    res.writeHead(403, { 'Content-Type': 'text/plain' });
    res.end('Forbidden: Invalid host header');
    return;
  }

  const parsed = url.parse(req.url);
  const pathname = parsed.pathname;

  if (pathname.startsWith('/api/proxy')) {
    await handleApiRequest(req, res, pathname);
  } else if (pathname === '/health') {
    res.writeHead(200);
    res.end('OK');
  } else {
    res.writeHead(404);
    res.end('Not found');
  }
});

server.listen(CONFIG.port, () => {
  console.log(`Server running on port ${CONFIG.port}`);
  console.log(`Host validation: ${CONFIG.enableHostValidation ? 'enabled' : 'disabled'}`);
});

module.exports = { server, validateHostHeader, isPrivateIP };
